// AUDIO.JS — synthesized coastal synthwave, a complaining engine and street effects.
// No audio files: every pad, siren and seagull is generated by oscillators and noise.

export const STATIONS = [
  { name: 'MAR ABIERTO 98.7', track: 'TIDE FM — SUNSET DRIVE', mood: 'slow' },
  { name: 'CORAL FM 104.2', track: 'NEON NOCTURNE — LIVE FROM THE PIER', mood: 'fast' },
  { name: 'RADIO SOL 88.8', track: 'GOLDEN HOUR — ACOUSTIC BAY', mood: 'acoustic' },
];

const midi = (note) => 440 * Math.pow(2, (note - 69) / 12);

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.started = false;
    this.station = 0;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.engineOsc = null;
    this.engineOsc2 = null;
    this.engineFilter = null;
    this.engineGain = null;
    this.sirenOsc = null;
    this.sirenGain = null;
    this.sirenActive = false;
    this.sirenDistance = Infinity;
    this.time = 0;
    this.step = 0;
    this.nextNoteTime = 0;
    this.scheduler = null;
    this.noise = null;
    this.paused = false;
    this.onStation = null;
  }

  init() {
    if (this.started) {
      this.ctx?.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.ctx.resume?.().catch(() => {});
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.62;
    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.ratio.value = 5;
    this.master.connect(compressor);
    compressor.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.16;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.4;
    this.sfxGain.connect(this.master);
    this.noise = this.makeNoiseBuffer();
    this.buildEngine();
    this.buildSiren();
    this.started = true;
    this.nextNoteTime = this.ctx.currentTime + 0.15;
    this.scheduler = setInterval(() => this.schedule(), 90);
    this.updateStation();
  }

  makeNoiseBuffer() {
    const length = this.ctx.sampleRate * 1.2;
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  buildEngine() {
    this.engineGain = this.ctx.createGain();
    this.engineGain.gain.value = 0.0001;
    this.engineFilter = this.ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 220;
    this.engineFilter.Q.value = 4.5;
    this.engineOsc = this.ctx.createOscillator();
    this.engineOsc.type = 'sawtooth';
    this.engineOsc.frequency.value = 42;
    this.engineOsc2 = this.ctx.createOscillator();
    this.engineOsc2.type = 'square';
    this.engineOsc2.frequency.value = 21.5;
    const mix2 = this.ctx.createGain();
    mix2.gain.value = 0.35;
    this.engineOsc.connect(this.engineFilter);
    this.engineOsc2.connect(mix2);
    mix2.connect(this.engineFilter);
    this.engineFilter.connect(this.engineGain);
    this.engineGain.connect(this.master);
    this.engineOsc.start();
    this.engineOsc2.start();
  }

  buildSiren() {
    this.sirenGain = this.ctx.createGain();
    this.sirenGain.gain.value = 0.0001;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 900;
    filter.Q.value = 2;
    this.sirenOsc = this.ctx.createOscillator();
    this.sirenOsc.type = 'sawtooth';
    this.sirenOsc.frequency.value = 740;
    this.sirenOsc.connect(filter);
    filter.connect(this.sirenGain);
    this.sirenGain.connect(this.master);
    this.sirenOsc.start();
  }

  schedule() {
    if (!this.ctx || this.ctx.state !== 'running') return;
    const station = STATIONS[this.station];
    const bpm = station.mood === 'fast' ? 108 : station.mood === 'acoustic' ? 84 : 78;
    const stepDur = 60 / bpm / 4;
    while (this.nextNoteTime < this.ctx.currentTime + 0.28) {
      this.scheduleStep(this.step, this.nextNoteTime, station);
      this.nextNoteTime += stepDur;
      this.step += 1;
    }
  }

  scheduleStep(step, time, station) {
    const bar = Math.floor(step / 16) % 4;
    const s = step % 16;
    if (station.mood === 'fast') {
      const roots = [50, 53, 48, 55];
      if (s % 4 === 0) this.playKick(time);
      if (s % 4 === 2) this.playHat(time, 0.05);
      if (s === 4 || s === 12) this.playSnare(time);
      if (s % 2 === 0) this.playBass(midi(roots[bar] - 12), time, 0.15, 0.09);
      if (s % 4 === 0) this.playPad([midi(roots[bar]), midi(roots[bar] + 7), midi(roots[bar] + 12)], time, 1.6, 0.026);
      const arp = [0, 7, 12, 16, 19, 16, 12, 7];
      if (s % 2 === 1) this.playPluck(midi(roots[bar] + 24 + arp[(step + bar) % arp.length]), time, 0.1, 0.045);
    } else if (station.mood === 'acoustic') {
      const roots = [45, 48, 41, 43];
      if (s === 0) this.playPad([midi(roots[bar] - 12), midi(roots[bar]), midi(roots[bar] + 7)], time, 3.8, 0.03);
      if (s % 4 === 0) this.playPluck(midi(roots[bar] + 12), time, 0.5, 0.055);
      if (s === 6 || s === 10) this.playPluck(midi(roots[bar] + 19), time, 0.35, 0.035);
      if (s === 8) this.playKick(time, 0.28);
      if (s === 14) this.playHat(time, 0.025);
    } else {
      const roots = [38, 41, 36, 43];
      if (s === 0 || s === 8) this.playKick(time, 0.38);
      if (s === 4 || s === 12) this.playSnare(time, 0.06);
      if (s % 4 === 0) this.playPad([midi(roots[bar]), midi(roots[bar] + 7), midi(roots[bar] + 12), midi(roots[bar] + 15)], time, 2.1, 0.028);
      if (s % 2 === 0) this.playBass(midi(roots[bar] - 12), time, 0.2, 0.07);
      if (s === 2 || s === 7 || s === 11 || s === 14) this.playPluck(midi(roots[bar] + 24 + (s % 4) * 2), time, 0.16, 0.03);
      if (s % 2 === 1) this.playHat(time, 0.018);
    }
    if (s === 0) {
      // faint tape hiss gives the mix a late-night radio texture
      this.playNoise(time, 0.5, 0.004, 3200, this.musicGain);
    }
  }

  playKick(time, gain = 0.35) {
    const osc = this.ctx.createOscillator();
    const env = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(120, time);
    osc.frequency.exponentialRampToValueAtTime(42, time + 0.16);
    env.gain.setValueAtTime(gain, time);
    env.gain.exponentialRampToValueAtTime(0.0001, time + 0.22);
    osc.connect(env).connect(this.musicGain);
    osc.start(time);
    osc.stop(time + 0.25);
  }

  playHat(time, gain = 0.04) {
    this.playNoise(time, 0.055, gain, 7200, this.musicGain);
  }

  playSnare(time, gain = 0.08) {
    this.playNoise(time, 0.16, gain, 1800, this.musicGain);
    const osc = this.ctx.createOscillator();
    const env = this.ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.value = 190;
    env.gain.setValueAtTime(gain * 0.8, time);
    env.gain.exponentialRampToValueAtTime(0.0001, time + 0.11);
    osc.connect(env).connect(this.musicGain);
    osc.start(time);
    osc.stop(time + 0.13);
  }

  playBass(freq, time, duration, gain) {
    const osc = this.ctx.createOscillator();
    const filter = this.ctx.createBiquadFilter();
    const env = this.ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.value = freq;
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(320, time);
    filter.frequency.exponentialRampToValueAtTime(130, time + duration);
    env.gain.setValueAtTime(0.0001, time);
    env.gain.linearRampToValueAtTime(gain, time + 0.012);
    env.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    osc.connect(filter).connect(env).connect(this.musicGain);
    osc.start(time);
    osc.stop(time + duration + 0.02);
  }

  playPluck(freq, time, duration, gain) {
    const osc = this.ctx.createOscillator();
    const env = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    osc.type = 'triangle';
    osc.frequency.value = freq;
    filter.type = 'lowpass';
    filter.frequency.value = 2600;
    env.gain.setValueAtTime(0.0001, time);
    env.gain.linearRampToValueAtTime(gain, time + 0.01);
    env.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    osc.connect(filter).connect(env).connect(this.musicGain);
    osc.start(time);
    osc.stop(time + duration + 0.02);
  }

  playPad(freqs, time, duration, gain) {
    freqs.forEach((freq, i) => {
      const osc = this.ctx.createOscillator();
      const detune = this.ctx.createOscillator();
      const detuneGain = this.ctx.createGain();
      const filter = this.ctx.createBiquadFilter();
      const env = this.ctx.createGain();
      osc.type = i === 0 ? 'sine' : 'triangle';
      osc.frequency.value = freq;
      detune.frequency.value = 0.18 + i * 0.03;
      detuneGain.gain.value = 4;
      detune.connect(detuneGain).connect(osc.frequency);
      filter.type = 'lowpass';
      filter.frequency.value = 1100;
      filter.Q.value = 0.5;
      env.gain.setValueAtTime(0.0001, time);
      env.gain.linearRampToValueAtTime(gain, time + 0.4);
      env.gain.linearRampToValueAtTime(gain * 0.7, time + duration * 0.65);
      env.gain.exponentialRampToValueAtTime(0.0001, time + duration);
      osc.connect(filter).connect(env).connect(this.musicGain);
      osc.start(time);
      detune.start(time);
      osc.stop(time + duration + 0.1);
      detune.stop(time + duration + 0.1);
    });
  }

  playNoise(time, duration, gain, cutoff, destination) {
    const source = this.ctx.createBufferSource();
    source.buffer = this.noise;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = cutoff;
    filter.Q.value = 0.7;
    const env = this.ctx.createGain();
    env.gain.setValueAtTime(gain, time);
    env.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    source.connect(filter).connect(env).connect(destination ?? this.sfxGain);
    source.start(time);
    source.stop(time + duration + 0.02);
  }

  update(dt, state) {
    if (!this.started || !this.ctx) return;
    this.time += dt;
    const speed = state?.player?.mode === 'car' ? Math.abs(state.player.car.speed) : 0;
    const targetGain = speed > 0.4 ? 0.025 + Math.min(0.04, speed * 0.0015) : 0.004;
    this.engineGain.gain.setTargetAtTime(targetGain, this.ctx.currentTime, 0.12);
    this.engineOsc.frequency.setTargetAtTime(34 + speed * 2.8, this.ctx.currentTime, 0.08);
    this.engineOsc2.frequency.setTargetAtTime(17 + speed * 1.4, this.ctx.currentTime, 0.08);
    this.engineFilter.frequency.setTargetAtTime(150 + speed * 22, this.ctx.currentTime, 0.1);
    if (this.sirenActive) {
      const proximity = Math.max(0, 1 - this.sirenDistance / 150);
      this.sirenGain.gain.setTargetAtTime(0.03 * proximity, this.ctx.currentTime, 0.2);
      this.sirenOsc.frequency.setTargetAtTime(690 + Math.sin(this.time * 4.4) * 190, this.ctx.currentTime, 0.08);
    } else {
      this.sirenGain.gain.setTargetAtTime(0.0001, this.ctx.currentTime, 0.3);
    }
  }

  siren(active, distance) {
    this.sirenActive = Boolean(active);
    this.sirenDistance = distance;
  }

  sfx(name) {
    if (!this.started || !this.ctx) return;
    const now = this.ctx.currentTime;
    switch (name) {
      case 'crash':
        this.playNoise(now, 0.34, 0.28, 900, this.sfxGain);
        this.playNoise(now + 0.03, 0.16, 0.16, 300, this.sfxGain);
        this.playSfxTone(now, 120, 0.25, 0.11, 'sawtooth');
        break;
      case 'hurt':
        this.playSfxTone(now, 140, 0.22, 0.14, 'triangle');
        this.playNoise(now, 0.16, 0.09, 480, this.sfxGain);
        break;
      case 'scream':
        this.playSfxTone(now, 720, 0.4, 0.05, 'sine', 300);
        break;
      case 'shoot':
        this.playNoise(now, 0.12, 0.3, 2200, this.sfxGain);
        this.playSfxTone(now, 86, 0.1, 0.2, 'square');
        break;
      case 'horn':
        this.playSfxTone(now, 392, 0.3, 0.05, 'square');
        this.playSfxTone(now, 494, 0.3, 0.035, 'square');
        break;
      case 'door':
        this.playSfxTone(now, 90, 0.08, 0.1, 'triangle');
        this.playNoise(now + 0.02, 0.08, 0.08, 400, this.sfxGain);
        break;
      case 'pickup':
        [0, 4, 7].forEach((semi, i) => this.playSfxTone(now + i * 0.05, midi(72 + semi), 0.2, 0.09, 'triangle'));
        break;
      case 'objective':
        this.playSfxTone(now, midi(76), 0.14, 0.07, 'sine');
        this.playSfxTone(now + 0.09, midi(83), 0.18, 0.06, 'sine');
        break;
      case 'mission':
        [0, 7, 12, 16].forEach((semi, i) => this.playSfxTone(now + i * 0.1, midi(62 + semi), 0.35, 0.05, 'triangle'));
        break;
      case 'success':
        [0, 4, 7, 12, 16].forEach((semi, i) => this.playSfxTone(now + i * 0.09, midi(67 + semi), 0.35, 0.07, 'triangle'));
        break;
      case 'fail':
        [0, -3, -7].forEach((semi, i) => this.playSfxTone(now + i * 0.18, midi(58 + semi), 0.55, 0.08, 'sawtooth'));
        break;
      case 'ui':
        this.playSfxTone(now, midi(81), 0.08, 0.045, 'sine');
        break;
      default:
        break;
    }
  }

  playSfxTone(time, freq, duration, gain, type = 'sine', endFreq = null) {
    const osc = this.ctx.createOscillator();
    const env = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(endFreq, time + duration);
    env.gain.setValueAtTime(0.0001, time);
    env.gain.linearRampToValueAtTime(gain, time + 0.01);
    env.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    osc.connect(env).connect(this.sfxGain);
    osc.start(time);
    osc.stop(time + duration + 0.02);
  }

  toggleStation() {
    this.station = (this.station + 1) % STATIONS.length;
    this.step = 0;
    if (this.ctx) this.nextNoteTime = this.ctx.currentTime + 0.08;
    this.updateStation();
    this.sfx('ui');
    return STATIONS[this.station];
  }

  updateStation() {
    this.onStation?.(STATIONS[this.station], this.station);
  }

  get stationInfo() {
    return STATIONS[this.station];
  }

  setPaused(paused) {
    if (!this.ctx) return;
    this.paused = paused;
    if (paused) this.ctx.suspend();
    else this.ctx.resume();
  }
}

